"""Explain completion call context, timeout boundary, IO and interruptible results."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1513': ('“잠시 기다려도 되는 자리”와 “지금 일을 멈추면 안 되는 자리”는 다릅니다. 함수 이름에 기다림이 들어 있으면 얼마나 기다릴지뿐 아니라 지금 기다려도 되는 상황인지 먼저 살펴야 합니다.', '완료 대기를 호출할 수 있는 상황과 실제 잠금 명령을 구별합니다.', 'might_sleep → complete_acquire → 잠금 잡기 → 공통 대기 → 잠금 풀기 → complete_release를 적으세요. 이 버전에서 본체가 빈 두 함수에는 빈 칸 표시를 하세요.', ['__wait_for_common은 여러 완료 대기 함수의 공통 입구입니다. 첫 might_sleep는 이 코드가 잠들 수 있는 경로라는 점을 알리고 잘못된 실행 상황을 검사하는 데 쓰입니다. 이름만 보고 이 명령 자체가 반드시 작업을 잠재운다고 생각하지 마세요.', '실행 문맥은 지금 코드가 어떤 상황에서 실행되는지를 뜻합니다. 완료 대기는 잠들 수 있는 일반 작업 문맥에서, 인터럽트가 켜져 있는 상태로 사용해야 합니다. 인터럽트 처리 중이거나 선점을 꺼서 실행을 넘길 수 없는 구간 등에 함부로 넣을 수 없습니다.', '공통 입구는 raw_spin_lock_irq로 잠금을 잡고 do_wait_for_common을 호출한 뒤 raw_spin_unlock_irq로 풉니다. 실제 기다림은 내부에서 잠금을 풀었다가 다시 잡는 구간에 있습니다. 잠금을 잡은 채 기다리는 것과 구별하세요.', '여기의 irq 쌍은 해당 CPU의 인터럽트를 끄고 켭니다. 이전 상태를 저장하는 irqsave와 복구하는 irqrestore 쌍이 아닙니다. 처음부터 꺼진 곳에서 부르면 끝에서 원치 않게 켜질 수 있으므로 호출 조건을 지켜야 합니다.', '잠금 앞뒤의 complete_acquire와 complete_release는 이 고정 버전 헤더에서 본체가 {}인 빈 inline 함수입니다. acquire와 release라는 이름만으로 별도의 CPU 메모리 순서 명령이 실행된다고 단정할 수 없습니다. 실제 순서 보장은 잠금과 깨움 구현 등 해당 코드를 따라 확인합니다.', '다른 mutex를 잡은 채 기다리는 경우도 상대 작업이 같은 mutex를 필요로 하는지 확인해야 합니다. 내가 열쇠를 쥐고 기다리는데 상대가 그 열쇠를 받아야 완료할 수 있으면 서로 진행하지 못합니다. 잠들 수 있는 문맥인지와 완료할 쪽이 진행할 수 있는지는 함께 살펴야 합니다.'], [('이 공통 입구의 raw_spin_lock_irq는 이전 인터럽트 상태도 저장하나요?', ['네. 모든 raw 잠금은 자동으로 이전 상태를 저장해요', '아니요. 여기서는 lock_irq와 unlock_irq를 사용해요'], 'irqsave·irqrestore가 아니라 irq 쌍입니다. 이전 상태를 담을 flags를 전달하는 형태도 없어요. 그래서 인터럽트가 켜진 적절한 상황에서 호출한다는 규칙이 중요합니다.'), ('이 버전의 complete_acquire 본체에 독립적인 CPU 명령이 적혀 있나요?', ['아니요. 헤더에서 빈 inline 함수로 정의돼 있어요', '네. 이름이 acquire이면 언제나 모든 순서를 보장해요'], '실제 정의의 본체는 {}입니다. 이름은 살펴볼 단서지만 실행 명령의 증거는 아니에요. 빈 함수와 실제 raw 잠금의 역할을 나누어 읽어야 합니다.')]), 'os1514': ('마감 종이 울렸을 때 완성된 숙제가 도착해 있다면 “못 받음”으로 처리하면 안 되겠지요. 시간 숫자가 0이어도 완료 표시가 있으면 성공을 나타내는 별도 숫자를 씁니다.', '완료 timeout의 경계 성공과 호출 조건을 이해합니다.', 'done=1·시간=0이면 표시를 하나 쓰고 결과 1, done=0·시간 만료면 결과 0을 적으세요. 두 결과의 뜻을 말로 설명하세요.', ['wait_for_completion_timeout은 완료를 일정 시간 기다립니다. 인자는 jiffies라는 커널 시간 눈금 단위입니다. 예를 들어 10은 반드시 10초가 아닙니다. 밀리초를 쓰려면 정해진 시간 변환 도우미 등을 이용해 단위를 맞춰야 합니다.', '이 함수는 TASK_UNINTERRUPTIBLE을 선택합니다. 일반 신호로 기다림을 중단하는 interruptible 변형과 다릅니다. 반환 형식 unsigned long은 음수 없는 정수 형식입니다. 이 함수의 결과는 완료하지 못한 시간 만료 0 또는 완료 성공인 양수입니다.', '대기 동작이 남은 시간 0을 돌려줘도 잠금을 다시 잡고 done을 확인합니다. 그때 완료 표시가 있다면 사용하고 성공으로 끝날 수 있습니다. 남은 시간이 0이라는 사실만 먼저 보고 결과를 실패로 확정하지 않습니다.', '공통 코드의 timeout ?: 1은 timeout이 0이면 1을 고르는 표현입니다. 성공 길에서 시간 0인 경우를 0 실패와 구별합니다. 따라서 결과 1은 정확히 한 눈금이 남았다는 뜻만 갖지 않습니다.', '처음부터 done이 있고 timeout=0이어도 표시를 소비해 1로 성공할 수 있습니다. 반면 done이 없으면 시간 인자가 0이어도 공통 준비와 대기 action 경로에 들어갈 수 있습니다. 공통 입구의 might_sleep와 인터럽트 조건도 그대로 남습니다.', '그러므로 “시간 0이니 잠들 수 없는 곳에서도 써도 된다”고 생각하면 안 됩니다. 그런 곳에서는 try_wait_for_completion처럼 기다리지 않고 확인·소비하는 별도 함수의 사용 조건을 살펴야 합니다. 기다림이 만료되어 돌아와도 작업 자체가 취소되거나 관련 자료를 바로 없애도 된다는 뜻은 아닙니다.'], [('남은 시간은 0이지만 완료 표시를 확인해 성공했어요. 결과는 무엇인가요?', ['무조건 실패를 뜻하는 0이에요', '성공을 구별하는 1이에요'], '완료 표시를 소비한 뒤 공통 코드는 timeout ?: 1을 반환합니다. 그래서 0인 잔여 시간도 성공 결과 1로 구별해요. 완료 표시가 없는 시간 만료의 0과 다릅니다.'), ('timeout을 0으로 주면 try_wait처럼 잠들 수 없는 곳에서도 같은 방식으로 써도 될까요?', ['아니요. 공통 대기의 실행 문맥 조건을 지켜야 해요', '네. 숫자 0이면 두 함수의 본체와 규칙이 같아져요'], '시간 인자만 바뀌었을 뿐 함수의 진입 검사와 잠금 방식은 남습니다. done이 없으면 내부 대기 경로도 갈 수 있어요. 즉시 확인용 API와 임의로 바꾸어 쓸 수 없습니다.')]), 'os1515': ('기다린 시간을 기록할 때 “일반 기다림”과 “입출력 때문에 기다림”을 나눠 적을 수 있습니다. 기록 항목을 바꾸는 것과 실제로 물건을 읽거나 보내는 일은 다릅니다.', 'I/O 대기의 함수 선택과 실제 입출력 요청을 구별합니다.', '일반 action=schedule_timeout, I/O action=io_schedule_timeout을 적고 둘 다 같은 완료 표시 검사로 연결하세요. 실제 요청 제출은 별도 칸에 두세요.', ['I/O는 input/output, 즉 입력과 출력의 줄임말입니다. completion의 I/O 변형은 이 기다림을 I/O 대기로 집계할 때 사용하는 함수입니다. 함수 이름에 I/O가 있다고 여기에서 곧바로 파일을 읽는 것은 아닙니다.', '일반 wait_for_common은 __wait_for_common의 action 자리에 schedule_timeout을 전달합니다. wait_for_common_io는 같은 자리에 io_schedule_timeout을 전달합니다. action은 공통 코드가 실제 기다릴 때 부를 함수입니다.', '두 변형 모두 같은 완료 자료의 done을 확인하고 같은 대기 줄을 사용합니다. 잠금을 풀고 선택된 action을 실행했다가 다시 잡는 기본 흐름과, 성공하면 일반 완료 표시 하나를 소비하는 규칙은 공통입니다.', 'I/O action은 기다리는 작업의 입출력 대기 집계와 스케줄링에 관련됩니다. 어떤 장치에 요청을 보낼지 정하거나 디스크 요청을 만들어 완료하는 코드는 별도로 있어야 합니다. 기다림 방식 선택만으로 실제 작업 요청이 생기지 않습니다.', '시간 제한 없는 wait_for_completion_io는 TASK_UNINTERRUPTIBLE과 MAX_SCHEDULE_TIMEOUT을 사용하며 반환 형식은 void입니다. void는 호출자에게 결과 숫자를 돌려주지 않는다는 뜻입니다. 내부에 시간 인자가 있어도 이 입구는 유한한 시간 제한을 두는 변형이 아닙니다.', 'wait_for_completion_io_timeout은 unsigned long 결과를 돌려줍니다. 완료하지 못하고 시간 만료면 0, 완료 성공이면 최소 1인 양수입니다. 예를 들어 남은 시간이 4라면 4, 경계에서 시간 0인데 완료 표시가 있다면 1입니다. I/O라는 이름이 반환값의 성공 약속을 음수로 바꾸지는 않습니다.'], [('I/O 공통 wrapper가 실제 기다릴 action으로 전달하는 함수는?', ['파일을 읽는 read 시스템 호출이에요', 'io_schedule_timeout이에요'], '원문은 __wait_for_common에 io_schedule_timeout을 전달합니다. 이 선택은 기다림 처리와 집계에 관련돼요. read를 실행하거나 디스크 요청을 직접 만드는 코드라고 읽으면 틀립니다.'), ('I/O timeout에서도 완료 성공은 최소 1인 양수인가요?', ['네. 공통 완료 처리의 반환 규칙을 사용해요', '아니요. I/O라는 이름이면 성공은 모두 음수예요'], '같은 공통 완료 대기를 사용하므로 시간 만료 0, 완료 성공 양수라는 약속이 유지됩니다. action 선택이 달라도 완료 표시 소비와 경계 성공 1은 공통입니다.')]), 'os1516': ('학교마다 성공 표시가 다를 수 있듯 함수마다 결과 숫자의 약속도 다릅니다. 어떤 기다림에서는 0이 성공이고, 시간 제한을 붙인 기다림에서는 0이 시간 초과입니다.', 'interruptible의 시간 제한 유무에 따른 반환값과 조건 우선을 구별합니다.', '시간 제한 없음: 0 성공·음수 신호 중단. 시간 제한 있음: 양수 성공·0 만료·음수 신호 중단의 두 줄 표를 만드세요.', ['interruptible은 허용된 신호를 받으면 기다림을 중단할 수 있다는 뜻입니다. wait_for_completion_interruptible은 공통 대기에 TASK_INTERRUPTIBLE을 전달합니다. 신호는 작업에게 보내는 알림이며 어떤 알림에 반응하는지는 상태와 규칙에 따릅니다.', '시간 제한 없는 이 wrapper는 내부 결과를 t에 받습니다. t가 -ERESTARTSYS이면 그 오류를 그대로 반환하고, 그 외 정상 완료이면 0을 돌려줍니다. 내부 성공 값이 양수여도 바깥 입구에서 0으로 바꾸어 주는 것입니다.', '그러므로 이 함수에서 결과 0은 성공입니다. 완료를 못 했다는 뜻으로 읽으면 안 됩니다. 반환 자료형은 int이며 정상 성공 0과 음수 중단 코드를 구별합니다. MAX_SCHEDULE_TIMEOUT은 이 입구에서 유한한 시간 제한 없이 기다리는 데 사용합니다.', '시간 제한을 붙인 wait_for_completion_interruptible_timeout은 long 결과를 사용합니다. 완료 성공이면 양수, 완료 없이 시간이 끝나면 0, 신호 중단이면 -ERESTARTSYS입니다. if(ret)만 보면 양수와 음수 모두 참이므로 성공 판단을 잘못할 수 있습니다.', '이미 done이 있으면 공통 함수는 대기 반복문을 건너뛰고 표시를 소비하는 길로 갑니다. 신호 검사는 done이 없을 때 들어가는 반복문 안에 있으므로, 준비된 완료 표시와 pending signal이 함께 있다고 언제나 신호 오류가 되는 것은 아닙니다. pending은 아직 처리할 알림이 남아 있다는 뜻입니다.', '예를 들어 잠금을 잡아 done=1을 확인했다면 이미 온 완료 표시를 사용해 0으로 만들고 성공할 수 있습니다. 시간 제한 없는 입구라면 최종 결과는 0입니다. 반면 표시가 없고 허용 신호 때문에 끝났다면 음수입니다. 입력 상태, 검사 순서, 바깥 반환 변환까지 함께 읽으세요.'], [('시간 제한 없는 wait_for_completion_interruptible이 정상 완료되면 결과는?', ['언제나 남은 jiffies 수를 그대로 돌려줘요', '0이에요'], 'wrapper는 -ERESTARTSYS만 오류로 전달하고 정상 완료는 return 0으로 바꿉니다. timeout 변형의 양수 성공과 구별해야 해요. 같은 completion 계열이라고 모든 반환 약속이 같지는 않습니다.'), ('이미 done=1인 경로에 처리할 신호도 있어요. 항상 신호 오류가 먼저인가요?', ['아니요. 준비된 표시를 소비하고 성공할 수 있어요', '네. 어떤 경로든 신호 검사가 가장 먼저예요'], '공통 함수의 신호 검사는 done이 없을 때의 반복문 안에 있습니다. 이미 표시가 있으면 그 반복을 거치지 않아요. 따라서 신호가 있다는 사실만으로 무조건 실패라고 결론 내리면 안 됩니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_374.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
